const exercises = [
  {id:'banded-squat',name:'Banded Squat',focus:'Lower body',equipment:'Long loop band',steps:['Stand on the band with feet just wider than hip-width and loop it over your shoulders.','Brace your core, sit your hips back, and bend your knees.','Drive through your whole foot to stand.'],tip:'Keep your knees tracking in the same direction as your toes.'},
  {id:'reverse-lunge',name:'Band Reverse Lunge',focus:'Lower body',equipment:'Long loop band',steps:['Stand on the center of the band and hold it at shoulder height.','Step one foot back and lower both knees with control.','Push through the front foot to return, then switch sides.'],tip:'Keep most of your weight through the front heel.'},
  {id:'banded-glute-bridge',name:'Banded Glute Bridge',focus:'Lower body',equipment:'Long loop band',steps:['Lie down, bend your knees, and place the band above them.','Press your knees gently outward and brace your core.','Squeeze your glutes to lift your hips, pause, then lower slowly.'],tip:'Stop when your shoulders, hips, and knees form one line.'},
  {id:'calf-raise',name:'Standing Calf Raise',focus:'Lower body',equipment:'Bodyweight',steps:['Stand tall with feet hip-width apart.','Rise onto the balls of your feet and pause.','Lower your heels slowly without bouncing.'],tip:'Use a wall lightly for balance if needed.'},
  {id:'banded-row',name:'Horizontal Band Row',focus:'Upper body',equipment:'Long loop band',steps:['Sit with legs extended and loop the band around your feet.','Keep your chest tall and pull your elbows toward your hips.','Squeeze your shoulder blades, then return slowly.'],tip:'Do not lean backward to create momentum.'},
  {id:'overhead-press',name:'Band Overhead Press',focus:'Upper body',equipment:'Long loop band',steps:['Stand on the band and hold it at shoulder height.','Brace your core and press your hands overhead.','Lower to your shoulders with control.'],tip:'Keep your ribs down instead of arching your lower back.'},
  {id:'band-pull-apart',name:'Band Pull-Apart',focus:'Upper body',equipment:'Long loop band',steps:['Hold the band in front of you at shoulder height.','Pull your hands apart until the band reaches your chest.','Return slowly while keeping your shoulders down.'],tip:'Use a wide grip to reduce resistance.'},
  {id:'bicep-curl',name:'Band Curls',focus:'Upper body',equipment:'Long loop band',steps:['Stand on the middle of the band with palms facing forward.','Keep elbows close to your sides and curl your hands upward.','Squeeze, then lower slowly.'],tip:'Keep your upper arms still throughout the rep.'},
  {id:'overhead-tricep-extension',name:'Overhead Tricep Ext with Band',focus:'Upper body',equipment:'Long loop band',steps:['Anchor one end under a foot and bring the other end behind your head.','Point your elbows forward and extend your arms overhead.','Bend your elbows slowly to return.'],tip:'Choose light tension and keep your neck relaxed.'},
  {id:'banded-tricep-pushdown',name:'Banded Tricep Pushdown',focus:'Upper body',equipment:'Long loop band + closed door',steps:['Loop the band securely over the top of a closed door and check the anchor.','Keep your elbows beside your ribs and begin with them bent.','Press your hands toward your thighs, straighten your elbows, then return slowly.'],tip:'Test the door and band with light tension before starting.'},
  {id:'chest-fly',name:'Band Chest Fly',focus:'Upper body',equipment:'Long loop band',steps:['Wrap the long loop band around your upper back and grip it directly with both hands.','Open your arms at shoulder height with a soft bend in your elbows.','Bring your hands together in front of your chest, squeeze, then return slowly.'],tip:'Keep your shoulders down and maintain the same elbow bend throughout.'},
  {id:'chair-dip',name:'Chair Dip',focus:'Upper body',equipment:'Sturdy chair',steps:['Place your hands on the front edge of a stable chair and move your hips just forward.','Bend your elbows to lower with your back close to the chair.','Press through your palms until your arms are straight.'],tip:'Keep the range small if your shoulders feel strained.'},
  {id:'push-up',name:'Push-Up',focus:'Upper body',equipment:'Bodyweight',steps:['Place your hands slightly wider than your shoulders.','Brace your body in one straight line and lower your chest.','Press the floor away to return.'],tip:'Use your knees or a sturdy raised surface to make it easier.'},
  {id:'plank',name:'Forearm Plank',focus:'Core',equipment:'Bodyweight',steps:['Place your elbows beneath your shoulders and extend your legs.','Brace your abdomen and squeeze your glutes.','Hold a straight line from head to heels while breathing.'],tip:'Stop the set when your lower back begins to sag.'},
  {id:'side-plank',name:'Side Plank',focus:'Core',equipment:'Bodyweight',steps:['Lie on your side with your elbow beneath your shoulder.','Lift your hips until your body forms a straight line.','Hold while keeping your hips stacked.'],tip:'Bend the lower knee for an easier version.'},
  {id:'crunch',name:'Sit-Ups',focus:'Core',equipment:'Bodyweight',steps:['Lie down with knees bent and feet planted.','Brace your abdomen and curl your torso toward your thighs.','Lower yourself slowly without pulling on your neck.'],tip:'Use a smaller range if your feet lift or your back feels strained.'},
  {id:'russian-twist',name:'Russian Twist',focus:'Core',equipment:'Bodyweight',steps:['Sit with knees bent, heels down, and lean back slightly.','Brace your core and rotate your shoulders to one side.','Return through center and rotate to the other side.'],tip:'Move your ribs, not only your hands.'},
  {id:'toe-touch',name:'Toe Touch (Lying Down)',focus:'Core',equipment:'Bodyweight',steps:['Lie on your back with your legs raised above your hips.','Reach your hands toward your toes by lifting your shoulder blades.','Lower with control while keeping your legs steady.'],tip:'Reach upward rather than pulling your head forward.'},
  {id:'scissors',name:'Scissors',focus:'Core',equipment:'Bodyweight',steps:['Lie on your back with straight legs hovering above the floor.','Raise one leg as the other stays low.','Switch legs smoothly while keeping your lower back supported.'],tip:'Lift both legs higher if your lower back begins to arch.'},
  {id:'knee-crunch',name:'Knee Crunches',focus:'Core',equipment:'Bodyweight',steps:['Lean back with your legs extended slightly above the floor.','Draw both knees toward your chest as your torso curls forward.','Extend your legs again without letting your heels touch down.'],tip:'Move slowly and keep your chest open.'},
  {id:'leg-raise',name:'Leg Raises',focus:'Core',equipment:'Bodyweight',steps:['Lie down with straight legs and arms beside you.','Brace your abdomen and raise both legs over your hips.','Lower them slowly, stopping before your back arches.'],tip:'Bend your knees slightly to reduce difficulty.'},
  {id:'bicycle-crunch',name:'Bicycle Crunch',focus:'Core',equipment:'Bodyweight',steps:['Lie down and lift your knees over your hips.','Rotate one shoulder toward the opposite knee as the other leg extends.','Switch sides slowly without pulling your neck.'],tip:'Slow reps keep the work in your core.'},
  {id:'bird-dog',name:'Bird Dog',focus:'Core',equipment:'Bodyweight',steps:['Start on hands and knees with your spine neutral.','Extend the opposite arm and leg without rotating your hips.','Pause, return, and switch sides.'],tip:'Imagine balancing a glass of water on your lower back.'},
  {id:'mountain-climber',name:'Mountain Climber',focus:'Cardio',equipment:'Bodyweight',steps:['Begin in a high plank with hands beneath your shoulders.','Drive one knee toward your chest.','Switch legs at a controlled, steady pace.'],tip:'Keep your hips level and shoulders over your wrists.'},
  {id:'plank-shoulder-tap',name:'Plank Shoulder Tap',focus:'Core',equipment:'Bodyweight',steps:['Begin in a high plank with feet set wide.','Lift one hand and tap the opposite shoulder.','Set it down and switch sides without rocking your hips.'],tip:'Move more slowly to make the core work harder.'},
  {id:'jumping-jack',name:'Jumping Jack',focus:'Cardio',equipment:'Bodyweight',steps:['Stand tall with arms at your sides.','Jump your feet apart as your arms travel overhead.','Jump back to the start and repeat smoothly.'],tip:'Step one foot out at a time for a low-impact version.'},
  {id:'squat-thrust',name:'Squat Thrust',focus:'Cardio',equipment:'Bodyweight',steps:['Squat and place your hands on the floor.','Step or jump your feet back into a high plank.','Return your feet to the squat and stand tall.'],tip:'Step back one foot at a time to lower the impact.'},
  {id:'burpee',name:'Burpees',focus:'Cardio',equipment:'Bodyweight',steps:['Squat, place your hands down, and move your feet into a high plank.','Return your feet toward your hands.','Stand or jump upward with your arms overhead, then repeat.'],tip:'Step your feet back and remove the jump for a lower-impact version.'},
  {id:'walking',name:'Brisk Walk',focus:'Recovery',equipment:'None',steps:['Walk at an easy pace for the first few minutes.','Build to a pace that raises your breathing while you can still talk.','Slow down for the final few minutes.'],tip:'Consistency matters more than speed.'}
  ,{id:'march-in-place',name:'March in Place',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Stand tall with your feet under your hips.','Lift one knee while the opposite arm moves forward.','Lower with control and alternate sides at an easy pace.'],tip:'Use this before every workout to raise your body temperature.'}
  ,{id:'arm-circles',name:'Arm Circles',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Stand tall and extend both arms at shoulder height.','Make small controlled circles without shrugging.','Gradually increase the circle, then reverse direction.'],tip:'Keep the motion smooth and pain-free.'}
  ,{id:'hip-circles',name:'Hip Circles',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Stand with your feet just wider than hip-width and place your hands on your hips.','Move your hips forward, to one side, back, and around in a smooth circle.','Complete the circles slowly, then reverse direction.'],tip:'Keep your feet planted and make the circle comfortable.'}
  ,{id:'arm-cross-over-stretch',name:'Arm Cross-Over Stretch',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Stand tall and bring one straight arm across your chest.','Support it above the elbow with your opposite forearm.','Hold gently, release, and switch sides.'],tip:'Keep the stretching shoulder relaxed and down.'}
  ,{id:'hamstring-stretch',name:'Standing Hamstring Stretch',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Place one heel slightly forward with the toes lifted.','Bend the support knee and hinge gently from your hips.','Hold, then return and switch sides.'],tip:'You should feel a gentle stretch behind the thigh, never pain.'}
  ,{id:'shoulder-stretch',name:'Shoulder Stretch',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Stand tall and clasp your hands behind your lower back.','Straighten your elbows and gently lift your hands away from your body.','Keep your chest open and release slowly.'],tip:'Use a small range and avoid forcing your shoulders.'}
  ,{id:'childs-pose',name:"Child's Pose",focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Kneel and lower your hips toward your heels.','Reach both arms forward as your torso folds down.','Breathe slowly and relax into a comfortable range.'],tip:'Place your hands closer if your shoulders feel strained.'}
  ,{id:'downward-facing-dog',name:'Downward-Facing Dog',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Begin on your hands and knees with hands slightly ahead of your shoulders.','Tuck your toes and lift your hips up and back.','Lengthen your spine and gently press your heels toward the floor.'],tip:'Bend your knees if your back rounds.'}
  ,{id:'standing-quadriceps-stretch',name:'Standing Quadriceps Stretch',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Stand tall and shift your weight onto one leg.','Hold the opposite ankle behind you and keep your knees close.','Gently draw the heel toward your glutes, then switch sides.'],tip:'Hold a wall lightly if you need help balancing.'}
  ,{id:'butterfly-stretch',name:'Butterfly Stretch',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Sit tall and bring the soles of your feet together.','Let your knees relax outward and hold your feet.','Hinge forward slightly while keeping your back long.'],tip:'Never press your knees down with force.'}
  ,{id:'triceps-stretch',name:'Triceps Stretch',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Lift one arm overhead and bend the elbow so your hand reaches down your back.','Use the opposite hand to guide the raised elbow gently inward.','Hold, release, and switch sides.'],tip:'Keep your ribs down and neck relaxed.'}
  ,{id:'upward-facing-dog',name:'Upward-Facing Dog Stretch',focus:'Stretching',equipment:'Bodyweight',required:true,steps:['Lie face down with your hands beside your lower ribs.','Press through your palms to lift your chest and straighten your arms.','Draw your shoulders down and keep your thighs active.'],tip:'Use Cobra Pose instead if this creates pressure in your lower back.'}
];

const weeks = [
  {name:'Lower Body',time:'40–45 min',note:'Strength · Legs and glutes',items:[['banded-squat','3 × 12–15'],['reverse-lunge','3 × 10 / side'],['banded-glute-bridge','3 × 15'],['calf-raise','3 × 18'],['plank','3 × 30–45 sec']]},
  {name:'Upper Body',time:'40–45 min',note:'Strength · Chest, back, shoulders and arms',items:[['banded-row','3 × 12–15'],['overhead-press','3 × 10–12'],['chest-fly','3 × 12'],['band-pull-apart','3 × 15'],['bicep-curl','3 × 12'],['overhead-tricep-extension','3 × 12'],['russian-twist','3 × 16 total']]},
  {name:'Cardio + Core',time:'40 min',note:'Circuit · 4 rounds',items:[['jumping-jack','40 sec'],['mountain-climber','30 sec'],['squat-thrust','10–12 reps'],['plank-shoulder-tap','16 total'],['crunch','12–15 reps'],['toe-touch','15 reps']]},
  {name:'Full Body',time:'40–45 min',note:'Strength circuit · 3 rounds',items:[['banded-squat','15 reps'],['banded-row','12 reps'],['push-up','8–12 reps'],['banded-glute-bridge','15 reps'],['overhead-press','10 reps'],['bicycle-crunch','16 total']]},
  {name:'Recovery + Core',time:'30–40 min',note:'Optional day · Keep it easy',items:[['walking','20–25 min'],['bird-dog','3 × 10 / side'],['side-plank','3 × 20–30 sec'],['russian-twist','3 × 16 total'],['toe-touch','3 × 15']]}
];

const stretchRoutine={warmup:[['March in place','60 sec'],['Arm circles','30 sec each way'],['Hip circles','30 sec each way'],['Arm cross-over stretch','20 sec / side'],['Standing hamstring stretch','30 sec / side'],['Standing quadriceps stretch','30 sec / side'],['Shoulder stretch','30 sec'],['Triceps stretch','30 sec / side']],cooldown:[['Butterfly stretch','45 sec'],['Downward-Facing Dog','30 sec'],['Upward-Facing Dog stretch','20–30 sec'],["Child's Pose",'45 sec']]};

const stretchBlock=()=>`<section class="stretch-routine"><div><span>Before every workout · 6–8 min</span><h3>Warm-up</h3><ul>${stretchRoutine.warmup.map(([n,d])=>`<li><strong>${n}</strong><small>${d}</small></li>`).join('')}</ul></div><div><span>After every workout · 3–5 min</span><h3>Cooldown stretches</h3><ul>${stretchRoutine.cooldown.map(([n,d])=>`<li><strong>${n}</strong><small>${d}</small></li>`).join('')}</ul></div></section>`;

const byId=id=>exercises.find(x=>x.id===id);const asset=id=>`assets/anatomy/${id}.png?v=8`;
let selectedDay=0;let activeFilter='All';let completed=JSON.parse(localStorage.getItem('move-completed')||'[]');
const strip=document.querySelector('#week-strip'),detail=document.querySelector('#session-detail');
function renderWeek(){strip.innerHTML=weeks.map((d,i)=>`<button class="day-card ${i===selectedDay?'is-active':''} ${completed.includes(i)?'is-complete':''}" data-day="${i}"><span class="day-num">DAY ${i+1}</span><strong>${d.name}</strong><small>${d.time}</small></button>`).join('');renderSession();updateProgress()}
function renderSession(){const d=weeks[selectedDay];detail.innerHTML=`<header class="session-header"><div class="session-title"><h2>Day ${selectedDay+1} · ${d.name}</h2><p>${d.note} · 45–60 sec rest · stretching included</p></div><button class="complete-session ${completed.includes(selectedDay)?'done':''}" id="complete-day">${completed.includes(selectedDay)?'Completed ✓':'Mark complete'}</button></header>${stretchBlock()}<div class="main-work-label"><span>Main workout</span></div><div class="exercise-list">${d.items.map(([id,dose])=>{const e=byId(id);return `<div class="exercise-row" role="button" tabindex="0" data-exercise="${id}"><img class="exercise-thumb" src="${asset(id)}" alt="${e.name} start and finish positions"><div><span class="exercise-name">${e.name}</span><span class="exercise-meta">${e.focus} · ${e.equipment}</span></div><div class="exercise-dose">${dose}<span> controlled</span></div></div>`}).join('')}</div>`}
function updateProgress(){document.querySelector('#progress-count').textContent=`${completed.length} of 5 sessions`;document.querySelector('#progress-bar').style.width=`${completed.length/5*100}%`}
strip.addEventListener('click',e=>{const b=e.target.closest('[data-day]');if(b){selectedDay=+b.dataset.day;renderWeek()}});
detail.addEventListener('click',e=>{if(e.target.closest('#complete-day')){completed=completed.includes(selectedDay)?completed.filter(x=>x!==selectedDay):[...completed,selectedDay];localStorage.setItem('move-completed',JSON.stringify(completed));renderWeek();return}const row=e.target.closest('[data-exercise]');if(row)openExercise(row.dataset.exercise)});
detail.addEventListener('keydown',e=>{const row=e.target.closest('[data-exercise]');if(row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openExercise(row.dataset.exercise)}});
document.querySelector('#reset-progress').addEventListener('click',()=>{completed=[];localStorage.removeItem('move-completed');renderWeek()});

const filterNames=['All','Lower body','Upper body','Core','Cardio','Recovery','Stretching'];
document.querySelector('#filters').innerHTML=filterNames.map(f=>`<button class="filter ${f==='All'?'is-active':''}" data-filter="${f}">${f}</button>`).join('');
function renderLibrary(){const q=document.querySelector('#search').value.trim().toLowerCase();const list=exercises.filter(e=>(activeFilter==='All'||e.focus===activeFilter)&&(`${e.name} ${e.focus} ${e.equipment}`.toLowerCase().includes(q)));document.querySelector('#result-count').textContent=`${list.length} exercise${list.length===1?'':'s'}`;document.querySelector('#exercise-grid').innerHTML=list.map(e=>`<button class="exercise-card" data-exercise="${e.id}"><span class="exercise-art"><img src="${asset(e.id)}" alt="${e.name} start and finish positions"></span><span class="card-copy"><strong>${e.name}</strong><span>${e.focus} · ${e.equipment}</span></span></button>`).join('');document.querySelector('#empty-state').hidden=!!list.length}
document.querySelector('#search').addEventListener('input',renderLibrary);document.querySelector('#filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;activeFilter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('is-active',x===b));renderLibrary()});document.querySelector('#exercise-grid').addEventListener('click',e=>{const b=e.target.closest('[data-exercise]');if(b)openExercise(b.dataset.exercise)});

const dialog=document.querySelector('#exercise-dialog');function openExercise(id){const e=byId(id);document.querySelector('#dialog-content').innerHTML=`<div class="dialog-art"><img src="${asset(id)}" alt="${e.name} start and finish positions"></div><div class="dialog-copy"><span class="tag">${e.focus} · ${e.equipment}</span><h2>${e.name}</h2><ol>${e.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="tip"><strong>Form cue:</strong> ${e.tip}</p></div>`;dialog.showModal()}
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
const defaultDose=e=>e.focus==='Cardio'?'40 seconds':e.focus==='Recovery'?'20 minutes':e.focus==='Core'?'3 × 12–16':'3 × 10–15';
let chosenExercises=new Set();
let chosenDoses={};
let customPlans=JSON.parse(localStorage.getItem('move-custom-plans')||'[]').map(p=>({...p,items:p.items.filter(i=>byId(i.id))})).filter(p=>p.items.length);

function builderFocus(){const value=document.querySelector('#custom-type').value;return ['Lower body','Upper body','Core','Cardio','Recovery'].includes(value)?value:null}
function renderBuilderExercises(){const q=document.querySelector('#builder-search').value.trim().toLowerCase();const focus=builderFocus();const list=exercises.filter(e=>!e.required&&(!focus||e.focus===focus)&&(`${e.name} ${e.focus}`.toLowerCase().includes(q)));document.querySelector('#builder-exercises').innerHTML=list.map(e=>`<label class="pick-card ${chosenExercises.has(e.id)?'is-selected':''}"><input type="checkbox" value="${e.id}" ${chosenExercises.has(e.id)?'checked':''}><img src="${asset(e.id)}" alt=""><span><strong>${e.name}</strong><small>${e.focus} · ${e.equipment}</small></span></label>`).join('');updateSelectedList()}
function updateSelectedList(){const selected=[...chosenExercises].map(byId).filter(Boolean);document.querySelector('#selection-count').textContent=`${selected.length} selected`;const box=document.querySelector('#selected-exercises');box.hidden=!selected.length;document.querySelector('#selected-list').innerHTML=selected.map(e=>`<label class="dose-row"><span><strong>${e.name}</strong><small>${e.focus}</small></span><input data-dose="${e.id}" value="${chosenDoses[e.id]||defaultDose(e)}" aria-label="Target for ${e.name}"><button type="button" data-remove="${e.id}" aria-label="Remove ${e.name}">×</button></label>`).join('')}
document.querySelector('#builder-exercises').addEventListener('change',e=>{if(!e.target.matches('input[type="checkbox"]'))return;e.target.checked?chosenExercises.add(e.target.value):chosenExercises.delete(e.target.value);renderBuilderExercises()});
document.querySelector('#builder-search').addEventListener('input',renderBuilderExercises);
document.querySelector('#custom-type').addEventListener('change',renderBuilderExercises);
document.querySelector('#selected-list').addEventListener('input',e=>{if(e.target.matches('[data-dose]'))chosenDoses[e.target.dataset.dose]=e.target.value});
document.querySelector('#selected-list').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;chosenExercises.delete(b.dataset.remove);delete chosenDoses[b.dataset.remove];renderBuilderExercises()});

function renderSavedPlans(){document.querySelector('#saved-count').textContent=`${customPlans.length} saved`;const root=document.querySelector('#saved-workouts');if(!customPlans.length){root.innerHTML='<div class="empty saved-empty">Your saved workouts will appear here.</div>';return}root.innerHTML=customPlans.map(p=>`<article class="custom-plan"><header><div><span>${p.day} · ${p.duration} min</span><h3>${p.type}</h3></div><button data-delete-plan="${p.id}" aria-label="Delete ${p.day} workout">Delete</button></header><div class="included-stretch">Warm-up + cooldown stretches included</div><ol>${p.items.map(i=>`<li><img src="${asset(i.id)}" alt=""><span><strong>${byId(i.id).name}</strong><small>${i.dose}</small></span></li>`).join('')}</ol></article>`).join('')}
document.querySelector('#saved-workouts').addEventListener('click',e=>{const b=e.target.closest('[data-delete-plan]');if(!b)return;customPlans=customPlans.filter(p=>p.id!==b.dataset.deletePlan);localStorage.setItem('move-custom-plans',JSON.stringify(customPlans));renderSavedPlans()});
document.querySelector('#plan-builder').addEventListener('submit',e=>{e.preventDefault();const message=document.querySelector('#builder-message');if(!chosenExercises.size){message.textContent='Select at least one exercise.';return}const items=[...chosenExercises].map(id=>({id,dose:(chosenDoses[id]||defaultDose(byId(id))).trim()}));customPlans.push({id:`plan-${Date.now()}`,day:document.querySelector('#custom-day').value,type:document.querySelector('#custom-type').value,duration:document.querySelector('#custom-duration').value,items});localStorage.setItem('move-custom-plans',JSON.stringify(customPlans));chosenExercises.clear();chosenDoses={};message.textContent='Workout saved.';document.querySelector('#builder-search').value='';renderBuilderExercises();renderSavedPlans();setTimeout(()=>message.textContent='',2500)});

document.querySelectorAll('.nav-link').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('is-active',x===btn));document.querySelectorAll('.view').forEach(v=>v.hidden=true);document.querySelector(`#${btn.dataset.view}-view`).hidden=false;if(btn.dataset.view==='library')renderLibrary();if(btn.dataset.view==='builder'){renderBuilderExercises();renderSavedPlans()}window.scrollTo({top:0,behavior:'smooth'})}));
renderWeek();renderLibrary();renderBuilderExercises();renderSavedPlans();
